PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS script_family (script_id TEXT PRIMARY KEY, canonical_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, family TEXT, writing_direction TEXT NOT NULL DEFAULT 'unknown', decipherment_status TEXT NOT NULL DEFAULT 'partial', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS source_document (document_id TEXT PRIMARY KEY, external_id TEXT, title TEXT, uri TEXT, media_type TEXT, checksum_sha256 TEXT, captured_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inscription (inscription_id TEXT PRIMARY KEY, document_id TEXT REFERENCES source_document(document_id), script_id TEXT NOT NULL REFERENCES script_family(script_id), scholarly_id TEXT, language_code TEXT, transliteration TEXT, translation TEXT, confidence REAL, uncertainty TEXT, provenance TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS glyph_observation (glyph_id TEXT PRIMARY KEY, inscription_id TEXT NOT NULL REFERENCES inscription(inscription_id) ON DELETE CASCADE, sequence_no INTEGER NOT NULL, unicode_codepoint TEXT, glyph_label TEXT, bounding_box TEXT, image_uri TEXT, recognized_text TEXT, confidence REAL, damaged INTEGER NOT NULL DEFAULT 0, alternate_readings TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(inscription_id,sequence_no));
CREATE TABLE IF NOT EXISTS reading (reading_id TEXT PRIMARY KEY, inscription_id TEXT NOT NULL REFERENCES inscription(inscription_id) ON DELETE CASCADE, reading_text TEXT NOT NULL, transliteration TEXT, normalized_text TEXT, confidence REAL, reviewer TEXT, evidence TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS translation_candidate (candidate_id TEXT PRIMARY KEY, reading_id TEXT NOT NULL REFERENCES reading(reading_id) ON DELETE CASCADE, target_language TEXT NOT NULL, translation TEXT NOT NULL, model_id TEXT, confidence REAL, rank_no INTEGER, evidence TEXT, human_verified INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS model_registry (model_id TEXT PRIMARY KEY, model_name TEXT NOT NULL UNIQUE, architecture TEXT, task TEXT, provider TEXT, license TEXT, metadata TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS model_version (model_version_id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES model_registry(model_id), version TEXT NOT NULL, artifact_uri TEXT, checksum_sha256 TEXT, parameters INTEGER, framework TEXT, metrics TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(model_id,version));
CREATE TABLE IF NOT EXISTS inference_run (run_id TEXT PRIMARY KEY, model_version_id TEXT REFERENCES model_version(model_version_id), inscription_id TEXT REFERENCES inscription(inscription_id), operation TEXT NOT NULL, input_hash TEXT, output TEXT, latency_ms REAL, confidence REAL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_inscription_script ON inscription(script_id);
CREATE INDEX IF NOT EXISTS ix_glyph_inscription ON glyph_observation(inscription_id);
